(function() local w={"Light","Regular","Medium","SemiBold","Bold","ExtraBold","Italic","Bold Italic"} local s=w[math.floor(UIT_Ctrl.Weight+0.5)+1] or "Regular" local f=UIT_Text.Font.Value if f=="Open Sans" then return s end local fam={["Arial"]=1,["Times New Roman"]=1,["Verdana"]=1,["Georgia"]=1,["Consolas"]=1,["Comic Sans MS"]=1,["Segoe UI"]=1,["Tahoma"]=1,["Calibri"]=1,["Cambria"]=1,["Courier New"]=1,["Trebuchet MS"]=1} if fam[f] then if s=="Light" or s=="Regular" or s=="Medium" then return "Regular" elseif s=="Italic" or s=="Bold Italic" then return s else return "Bold" end end return "Regular" end)()